"kind": "propose",
"summary": "The container's memory limit is too low, causing OOM kills. Increase the memory limit to prevent this.",
"hypotheses": [
    {
        "root_cause_class": "memory_limit_too_low",
        "summary": "The container's memory limit is 60Mi, but it peaked at 95% of that (57Mi) before being OOMKilled. The limit is insufficient for the workload.",
        "supporting": ["ev-pod_states", "ev-container_memory"],
        "contradicting": [],
        "missing": ["container_memory_peak_details", "oom_killed_reason_details"],
        "status": "supported"
    },
    {
        "root_cause_class": "memory_limit_regression",
        "summary": "The new revision's memory limit is lower than required, leading to OOM kills despite no prior revision for comparison.",
        "supporting": ["ev-rollout_history", "ev-container_memory"],
        "contradicting": [],
        "missing": ["previous_revision_memory_limit"],
        "status": "supported"
    }
],
"proposal": {
    "capability": "deployment.set-resources",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "shop",
        "name": "catalog",
        "uid": "uid-deployment-catalog"
    },
    "params": {
        "containers": {
            "app": {
                "limits": {
                    "memory": "90Mi"
                }
            }
        }
    },
    "expected_effect": "The memory limit for the app container will be increased to 90Mi, preventing OOM kills by providing sufficient memory headroom.",
    "rationale": "The container's memory limit is 60Mi, but it peaked at 95% of that (57Mi) before being OOMKilled. Increasing the limit to 90Mi provides a 25% buffer to prevent future OOM kills.",
    "cited_evidence_ids": ["ev-container_memory", "ev-pod_states"],
    "cited_predicates": ["oom_killed_current_revision", "memory_at_limit_before_kill", "memory_data_available"]
}
}
